import sys

def generate_graph(k):
    if k == 1:
        return 2, ["NY", "YN"]

    n = 2
    while True:
        if k <= (n - 1) * (n - 2) // 2 + 1:
            break
        n += 1

    graph = [["N"] * n for _ in range(n)]
    graph[0][1] = "Y"
    graph[1][0] = "Y"

    count = 1
    for i in range(2, n):
        graph[0][i] = "Y"
        graph[i][0] = "Y"
        for j in range(1, i):
            if count < k:
                graph[j][i] = "Y"
                graph[i][j] = "Y"
                count += 1
            else:
                break

    return n, ["".join(row) for row in graph]

def main():
    k = int(sys.stdin.read().strip())
    n, graph = generate_graph(k)
    sys.stdout.write(f"{n}\n")
    for line in graph:
        sys.stdout.write(f"{line}\n")

if __name__ == "__main__":
    main()
